using System.Linq;
using GPC.Checkers.Concrete.Shear;
using GPC.Model.Standards;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace ConcreteTests
{
    // Independent Python calculation recorded in ANTHEA F4.3b:
    // NTC 2018 4.1.23, bw=1000, d=350, Ac=400000, Asl=1500 mm²,
    // fck=30, fcd=17 MPa, gammaC=1.5. Values are not generated by the API.
    [TestClass]
    public class WallShearAxialTests
    {
        [DataTestMethod]
        [DataRow(0.0, 172771.0814352394, 0.0)]
        [DataRow(-400000.0, 225271.0814352394, 1.0)]
        [DataRow(-1360000.0, 351271.0814352394, 3.4)]
        [DataRow(-2000000.0, 351271.0814352394, 3.4)]
        public void WallStripCompressionAndCapMatchIndependentValues(double n, double expected, double sigma)
        {
            var result = Calculate(n);
            Assert.AreEqual(expected, result.VRd, 1e-6, "resistance N");
            Assert.AreEqual(sigma, result.Details.Single(x => x.Symbol == "σcp").Value, 1e-12);
            Assert.AreEqual(200000 / expected, result.Ratio.Value, 1e-12);
            Assert.AreEqual(n == 0 ? ShearVerdict.NotSatisfied : ShearVerdict.Satisfied, result.Verdict);
        }

        [TestMethod]
        public void WallStripTensionMustNotBeCertifiedByTheCompressionFormula()
        {
            var result = Calculate(40000);
            Assert.AreEqual(ShearVerdict.NotEvaluated, result.Verdict);
            Assert.IsFalse(result.Ratio.HasValue);
        }

        private static SectionShearResult Calculate(double n) => SectionShearCalculator.Calculate(
            new SectionShearInput(new StandardNTC2018Concrete(), n, 200000, 0,
                400000, 1000, 350, 1500, 30, 17, 391.3, 1.5, 200000, 0, 1));
    }
}
